CREATE TABLE IF NOT EXISTS governed_production_plans(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,created_by TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('blocked','pending_approval','executable','released','in_production','completed','cancelled')),plan JSONB NOT NULL,plan_digest CHAR(64) NOT NULL,blockers JSONB NOT NULL DEFAULT '[]',approvals JSONB NOT NULL DEFAULT '{}',haccp_release JSONB,version INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS governed_production_events(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,plan_id TEXT NOT NULL REFERENCES governed_production_plans(id),actor_id TEXT NOT NULL,event_type TEXT NOT NULL,detail JSONB NOT NULL DEFAULT '{}',occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS governed_production_events_lookup ON governed_production_events(tenant_id,plan_id,occurred_at);
CREATE INDEX IF NOT EXISTS governed_production_lots ON governed_production_plans USING GIN((plan->'sourceLots'));
CREATE OR REPLACE FUNCTION reject_governed_production_event_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'governed production events are append-only'; END $$;
DROP TRIGGER IF EXISTS governed_production_events_append_only ON governed_production_events;
CREATE TRIGGER governed_production_events_append_only BEFORE UPDATE OR DELETE ON governed_production_events FOR EACH ROW EXECUTE FUNCTION reject_governed_production_event_mutation();
